import { axiosClient } from '../../../shared/api/axiosClient';
import { ComparativaResponse } from '../types';

export interface RecursoDisponible {
  vehiculos: Array<{ id: number; placa: string; marca: string; modelo?: string; tipo?: string; label?: string; nivel_combustible?: { valor: number; label: string } }>;
  motoristas: Array<{ id: number; nombre: string; dui?: string; telefono?: string }>;
}

export const solicitudApi = {
  getComparativa: async (id: string): Promise<ComparativaResponse> => {
    const response = await axiosClient.get<ComparativaResponse>(`/solicitudes-transporte/${id}/comparativa`);
    return response.data;
  },

  aprobarConDecision: async (id: string, decision_final: 'operativo' | 'sistema' | 'manual', comentario: string, vehiculo_id?: number, motorista_id?: number) => {
    interface AprobarPayload {
      decision_final: 'operativo' | 'sistema' | 'manual';
      comentario: string;
      vehiculo_id?: number;
      motorista_id?: number;
    }
    const payload: AprobarPayload = { decision_final, comentario };
    if (vehiculo_id) payload.vehiculo_id = vehiculo_id;
    if (motorista_id) payload.motorista_id = motorista_id;
    const response = await axiosClient.post(`/solicitudes-transporte/${id}/aprobar-con-decision`, payload);
    return response.data;
  },

  desbloquear: async (id: string) => {
    const response = await axiosClient.post(`/solicitudes-transporte/${id}/desbloquear`);
    return response.data;
  },

  programar: async (id: string) => {
    const response = await axiosClient.post(`/solicitudes-transporte/${id}/programar`);
    return response.data;
  },

  rechazar: async (id: string, comentario: string) => {
    const response = await axiosClient.post(`/solicitudes-transporte/${id}/rechazar`, { comentario });
    return response.data;
  },

  // Nuevo: Reasignar motorista/veh├¡culo de un viaje ya aprobado
  reasignar: async (codigo: string, vehiculo_id: number, motorista_id: number, motivo_reasignacion: string) => {
    const response = await axiosClient.put(`/solicitudes-transporte/${codigo}/reasignar`, {
      vehiculo_id,
      motorista_id,
      motivo_reasignacion
    });
    return response.data;
  },

  // Nuevo: Obtener recursos disponibles para reasignaci├│n
  getRecursosDisponibles: async (fecha_salida?: string, fecha_retorno?: string): Promise<RecursoDisponible> => {
    const params: any = {};
    if (fecha_salida) params.fecha_salida = fecha_salida;
    if (fecha_retorno) params.fecha_retorno = fecha_retorno;
    const response = await axiosClient.get<RecursoDisponible>('/recursos/disponibles', { params });
    return response.data;
  },

  // Nuevo: A├▒adir un destino adicional a una solicitud que ya est├í en curso (EN_EJECUCION)
  addDestinoEnEjecucion: async (codigo: string, destino_adicional: string, lat?: number, lng?: number) => {
    const payload: any = { nombre: destino_adicional };
    if (lat !== undefined && lng !== undefined) {
      payload.lat = lat;
      payload.lng = lng;
    }
    const response = await axiosClient.post(`/solicitudes-transporte/${codigo}/destino-en-ejecucion`, payload);
    return response.data;
  }
};

import { axiosClient } from '../../../shared/api/axiosClient';
import { ComparativaCombustibleResponse } from '../types';

export const solicitudCombustibleApi = {
  getComparativa: async (id: string): Promise<ComparativaCombustibleResponse> => {
    const response = await axiosClient.get<ComparativaCombustibleResponse>(`/solicitudes-combustible/${id}/comparativa`);
    return response.data;
  },

  aprobar: async (id: string, comentario?: string) => {
    const payload: any = {};
    if (comentario) payload.observaciones = comentario;
    else payload.observaciones = 'Aprobado por jefatura'; // Fallback por si acaso, aunque el backend lo requiere
    const response = await axiosClient.post(`/solicitudes-combustible/${id}/aprobar`, payload);
    return response.data;
  },

  observacion: async (id: string, comentario: string) => {
    const response = await axiosClient.post(`/solicitudes-combustible/${id}/observacion`, { observaciones: comentario });
    return response.data;
  },

  preAprobar: async (id: string, comentario: string) => {
    const response = await axiosClient.post(`/solicitudes-combustible/${id}/pre-aprobar`, { observaciones: comentario });
    return response.data;
  },

  aprobarConDecision: async (id: string, decision_final: 'operativo' | 'jefe', comentario: string, monto_aprobado?: number) => {
    const payload: any = {
      decision_final,
      comentario
    };
    if (decision_final === 'jefe' && monto_aprobado !== undefined) {
      payload.monto_aprobado = monto_aprobado;
    }

    const response = await axiosClient.post(`/solicitudes-combustible/${id}/aprobar-con-decision`, payload);
    return response.data;
  },



  rechazar: async (id: string, comentario: string) => {
    const response = await axiosClient.post(`/solicitudes-combustible/${id}/rechazar`, { motivo: comentario });
    return response.data;
  }
};

import React from 'react';
import { AsignacionOperativo } from '../types';
import { Car, User, MessageSquare } from 'lucide-react';

interface ColumnaOperativoProps {
  data: AsignacionOperativo | null;
  isSelected: boolean;
  onSelect: () => void;
  isFaded: boolean;
}

export const ColumnaOperativo: React.FC<ColumnaOperativoProps> = ({ data, isSelected, onSelect, isFaded }) => {
  if (!data) {
    return (
      <div className="bg-white rounded-xl p-6 shadow-sm border border-slate-200 flex flex-col h-full items-center justify-center text-center">
        <div className="w-12 h-12 bg-slate-100 rounded-lg flex items-center justify-center mb-4">
          <User className="text-slate-400" size={24} />
        </div>
        <p className="text-sm font-bold text-slate-800">Sin Asignaci├│n Manual</p>
        <p className="text-xs text-slate-500 mt-1">A├║n no hay asignaci├│n por parte de operaciones.</p>
      </div>
    );
  }

  return (
    <div 
      onClick={onSelect}
      className={`bg-white rounded-xl p-6 shadow-sm border-2 cursor-pointer transition-colors flex flex-col h-full ${
        isSelected ? 'border-primary' : 'border-transparent hover:border-slate-300'
      } ${isFaded ? 'opacity-60 grayscale-[30%]' : ''}`}
      style={{
        boxShadow: isSelected ? '0 0 0 1px rgba(59, 130, 246, 0.1)' : '0 1px 3px rgba(0, 0, 0, 0.05)'
      }}
    >
      <div className="flex justify-between items-start mb-5 pb-4 border-b border-slate-200">
        <div>
          <h3 className="font-bold text-slate-800 text-lg tracking-tight">Asignaci├│n Manual</h3>
          <p className="text-xs text-slate-500 mt-1">Por Operador: {data.autor}</p>
        </div>
        <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${
          isSelected ? 'border-primary bg-primary' : 'border-slate-300'
        }`}>
          {isSelected && <div className="w-2 h-2 rounded-full bg-white" />}
        </div>
      </div>

      <div className="space-y-4 flex-1">
        <ResourceCard 
          icon={<Car size={16} />} 
          title="Veh├¡culo Asignado"
          name={data.vehiculo.placa}
          subtitle={data.vehiculo.modelo}
          fuel={data.vehiculo.nivel_combustible}
        />

        <ResourceCard 
          icon={<User size={16} />} 
          title="Motorista Asignado"
          name={data.motorista.nombre}
          hours={data.motorista.horas_periodo_7d}
        />

        {data.cambio_detectado !== 'ninguno' && data.justificacion && (
          <div className="bg-amber-50 border border-amber-200 p-4 rounded-lg mt-auto">
            <p className="text-[11px] font-bold text-amber-800 uppercase tracking-wider mb-2 flex items-center gap-1.5">
              <MessageSquare size={14} /> Justificaci├│n Operativa
            </p>
            <p className="text-sm text-amber-900 italic">"{data.justificacion}"</p>
          </div>
        )}
      </div>
    </div>
  );
};

const ResourceCard = ({ icon, title, name, subtitle, fuel, hours }: any) => (
  <div className="border border-slate-200 rounded-lg p-3 flex flex-col gap-3 bg-slate-50">
    <div className="flex gap-3">
      <div className="w-10 h-10 rounded text-slate-500 bg-white border border-slate-200 flex items-center justify-center shrink-0">
        {icon}
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{title}</p>
        <p className="text-sm font-semibold text-slate-800 truncate">{name}</p>
        {subtitle && <p className="text-xs text-slate-500 truncate mt-0.5">{subtitle}</p>}
        {hours !== undefined && <p className="text-xs text-slate-500 mt-0.5 font-medium">Manejo 7D: <span className="text-slate-800">{hours} hrs</span></p>}
      </div>
    </div>
    {fuel && fuel.valor !== undefined && (
      <div className="pt-2 mt-1 border-t border-slate-200">
        <div className="flex justify-between items-center mb-1.5">
          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Nivel de Combustible</span>
          <span className="text-xs font-bold text-slate-700">{fuel.label}</span>
        </div>
        <div className="w-full h-1.5 bg-slate-200 rounded-full overflow-hidden">
          <div className={`h-full ${fuel.valor > 20 ? 'bg-success' : 'bg-danger'}`} style={{ width: `${fuel.valor}%` }} />
        </div>
      </div>
    )}
  </div>
);

