import React, { useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMap } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { MapPin, AlertCircle } from 'lucide-react';

// Soluci├│n al problema de iconos por defecto de Leaflet con Vite/Webpack
delete (L.Icon.Default.prototype as any)._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: '/assets/leaflet/marker-icon-2x.png',
  iconUrl: '/assets/leaflet/marker-icon.png',
  shadowUrl: '/assets/leaflet/marker-shadow.png',
});

// Componente para ajustar los l├¡mites del mapa (zoom) a los marcadores
const MapBounds: React.FC<{ bounds: L.LatLngBoundsExpression }> = ({ bounds }) => {
  const map = useMap();
  useEffect(() => {
    if (bounds) {
      map.fitBounds(bounds, { padding: [50, 50] });
    }
  }, [bounds, map]);
  return null;
};

interface MapaViajeProps {
  origen: string;
  destino: string;
  origen_lat?: number | null;
  origen_lng?: number | null;
  destino_lat?: number | null;
  destino_lng?: number | null;
}

export const MapaViaje: React.FC<MapaViajeProps> = ({
  origen,
  destino,
  origen_lat,
  origen_lng,
  destino_lat,
  destino_lng
}) => {
  const hasCoordinates = origen_lat != null && origen_lng != null && destino_lat != null && destino_lng != null;

  // Centro por defecto: El Salvador
  const defaultCenter: [number, number] = [13.6929, -88.8181];
  const defaultZoom = 8;

  const originPos: [number, number] | null = (origen_lat != null && origen_lng != null) ? [origen_lat, origen_lng] : null;
  const destPos: [number, number] | null = (destino_lat != null && destino_lng != null) ? [destino_lat, destino_lng] : null;

  const bounds: L.LatLngTuple[] = [];
  if (originPos) bounds.push(originPos);
  if (destPos) bounds.push(destPos);

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-full relative">
      {!hasCoordinates && (
        <div className="absolute top-4 left-1/2 -translate-x-1/2 z-[1000] bg-amber-50 border border-amber-200 shadow-md text-amber-800 px-4 py-2 rounded-full text-xs font-bold flex items-center gap-2">
          <AlertCircle size={14} /> El sistema no registr├│ coordenadas exactas para este viaje.
        </div>
      )}

      <div className="flex-1 w-full h-full min-h-[400px] z-0">
        <MapContainer 
          center={originPos || defaultCenter} 
          zoom={originPos ? 13 : defaultZoom} 
          scrollWheelZoom={true} 
          style={{ height: '100%', width: '100%', zIndex: 10 }}
        >
          <TileLayer
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />

          {originPos && (
            <Marker position={originPos}>
              <Popup>
                <div className="font-bold text-slate-800">Origen</div>
                <div className="text-xs text-slate-600">{origen}</div>
              </Popup>
            </Marker>
          )}

          {destPos && (
            <Marker position={destPos}>
              <Popup>
                <div className="font-bold text-slate-800">Destino</div>
                <div className="text-xs text-slate-600">{destino}</div>
              </Popup>
            </Marker>
          )}

          {bounds.length === 2 && <MapBounds bounds={bounds} />}
        </MapContainer>
      </div>

      <div className="bg-slate-50 p-4 border-t border-slate-200 z-20">
        <div className="flex items-start gap-3 mb-2">
          <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center shrink-0 mt-1">
            <MapPin size={16} />
          </div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Punto de Partida</p>
            <p className="text-sm font-medium text-slate-800">{origen}</p>
          </div>
        </div>
        <div className="flex items-start gap-3">
          <div className="w-8 h-8 rounded-full bg-red-100 text-red-600 flex items-center justify-center shrink-0 mt-1">
            <MapPin size={16} />
          </div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Destino Oficial</p>
            <p className="text-sm font-medium text-slate-800">{destino}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { X, MapPin } from 'lucide-react';
import { toast } from 'sonner';
import { solicitudApi } from '../api/solicitudApi';
import { MapContainer, TileLayer, Marker, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';

// Soluci├│n al problema de iconos por defecto de Leaflet
delete (L.Icon.Default.prototype as any)._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

function LocationMarker({ position, setPosition, setDestino }: { position: L.LatLng | null, setPosition: (pos: L.LatLng) => void, setDestino: (dest: string) => void }) {
  useMapEvents({
    async click(e) {
      setPosition(e.latlng);
      try {
        const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${e.latlng.lat}&lon=${e.latlng.lng}`);
        const data = await response.json();
        if (data && data.display_name) {
          // Tomamos el nombre, pero lo limpiamos un poco si es muy largo
          const address = data.display_name.split(',').slice(0, 3).join(',');
          setDestino(address);
        }
      } catch (error) {
        console.error("Error al obtener la direcci├│n:", error);
      }
    },
  });
  return position === null ? null : <Marker position={position}></Marker>;
}

interface ModalDestinoAdicionalProps {
  isOpen: boolean;
  onClose: () => void;
  solicitudId: string;
  onSuccess: () => void;
}

export function ModalDestinoAdicional({ isOpen, onClose, solicitudId, onSuccess }: ModalDestinoAdicionalProps) {
  const [destino, setDestino] = useState('');
  const [position, setPosition] = useState<L.LatLng | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!destino.trim()) {
      toast.error('El destino es obligatorio');
      return;
    }

    try {
      setIsSubmitting(true);
      await solicitudApi.addDestinoEnEjecucion(solicitudId, destino, position?.lat, position?.lng);
      toast.success('Destino adicional registrado y motorista notificado');
      setDestino('');
      setPosition(null);
      onSuccess();
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Error al a├▒adir el destino');
    } finally {
      setIsSubmitting(false);
    }
  };

  const defaultCenter: [number, number] = [13.6929, -88.8181]; // Centro de El Salvador

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-in fade-in duration-200 overflow-y-auto">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-200 my-auto">
        <div className="flex items-center justify-between p-6 border-b border-slate-100 bg-slate-50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-[#859BFF]/10 flex items-center justify-center text-[#859BFF]">
              <MapPin size={20} />
            </div>
            <div>
              <h2 className="text-lg font-bold text-slate-800">A├▒adir Destino</h2>
              <p className="text-sm text-slate-500">Modificar ruta en ejecuci├│n</p>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6">
          <div className="mb-4">
            <label className="block text-sm font-bold text-slate-700 mb-2">Nuevo Destino Adicional</label>
            <textarea
              value={destino}
              onChange={(e) => setDestino(e.target.value)}
              placeholder="Ej: Ministerio de Hacienda, San Salvador..."
              className="w-full px-4 py-3 border border-slate-300 rounded-xl text-sm focus:outline-none focus:border-[#859BFF] focus:ring-2 focus:ring-[#859BFF]/20 transition-all resize-none min-h-[80px]"
              autoFocus
            />
          </div>

          <div className="mb-6">
            <label className="block text-sm font-bold text-slate-700 mb-2">Punto en el Mapa (Opcional)</label>
            <p className="text-xs text-slate-500 mb-2">Haz clic en el mapa para marcar la ubicaci├│n exacta del destino.</p>
            <div className="w-full h-[250px] rounded-xl overflow-hidden border border-slate-300 relative z-0">
              <MapContainer 
                center={defaultCenter} 
                zoom={8} 
                scrollWheelZoom={true} 
                style={{ height: '100%', width: '100%', zIndex: 10 }}
              >
                <TileLayer
                  attribution='&copy; OpenStreetMap'
                  url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                />
                <LocationMarker position={position} setPosition={setPosition} setDestino={setDestino} />
              </MapContainer>
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t border-slate-100">
            <button
              type="button"
              onClick={onClose}
              disabled={isSubmitting}
              className="px-5 py-2.5 text-slate-600 font-bold bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors text-sm disabled:opacity-50"
            >
              Cancelar
            </button>
            <button
              type="submit"
              disabled={isSubmitting || !destino.trim()}
              className="px-5 py-2.5 text-white font-bold bg-[#859BFF] hover:bg-[#7288f5] rounded-lg shadow-md transition-all text-sm flex items-center gap-2 disabled:opacity-60 disabled:cursor-not-allowed"
            >
              {isSubmitting ? (
                <>
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  Procesando...
                </>
              ) : (
                'Guardar y Notificar'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { RecentRequest } from '../api/dashboardApi';
import { Pagination } from '../../../shared/components/Pagination';

interface RecentTableProps {
  requests: RecentRequest[];
  isLoading: boolean;
}

export const RecentTable: React.FC<RecentTableProps> = ({ requests, isLoading }) => {
  const navigate = useNavigate();

  // Filtrar solo las solicitudes pre-aprobadas, ya que al Jefe solo le interesan estas para aprobar
  const safeRequests = requests || [];
  const preAprobadas = safeRequests.filter(req => {
    if (!req.status) return false;
    const statusVal = typeof req.status === 'string' ? req.status : (req.status as any).value || '';
    const s = statusVal.toLowerCase();
    return s.includes('pre_aprobada') || s.includes('pre');
  });

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;
  const totalPages = Math.ceil(preAprobadas.length / itemsPerPage);
  const paginatedRequests = preAprobadas.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const getStatusBadge = (status: any) => {
    let colorClass = "border-amber-200 text-amber-600";
    let dotClass = "bg-amber-500";
    let text = "pendiente";

    const statusVal = typeof status === 'string' ? status : status?.value || '';
    if (statusVal.toLowerCase().includes('pre')) {
      colorClass = "border-emerald-200 text-emerald-600";
      dotClass = "bg-emerald-500";
      text = "pre_aprobada";
    }

    return (
      <span className={`px-3 py-1 bg-white border ${colorClass} rounded-full text-[11px] font-semibold flex items-center w-max shadow-sm`}>
        <span className={`w-1.5 h-1.5 rounded-full ${dotClass} mr-1.5`}></span>
        {text}
      </span>
    );
  };

  return (
    <div className="bg-white rounded-2xl shadow-[0_2px_10px_-4px_rgba(0,0,0,0.05)] border border-slate-100/80 overflow-hidden mt-8">
      <div className="p-6 border-b border-slate-100/80 flex justify-between items-center bg-white">
        <div>
          <h3 className="font-extrabold text-[#182645] text-lg tracking-tight">Solicitudes recientes</h3>
          <p className="text-xs text-slate-400 mt-1 font-medium">├Ültimas solicitudes registradas en el sistema</p>
        </div>
        <button className="flex items-center gap-1.5 text-xs font-semibold text-slate-600 bg-white border border-slate-200 px-3 py-1.5 rounded-lg shadow-sm hover:bg-slate-50 transition-colors">
          Ver todas <span>&rarr;</span>
        </button>
      </div>

      {/* Mobile View (Cards) */}
      <div className="md:hidden flex flex-col p-4 gap-3">
        {isLoading ? (
          [1, 2, 3].map(i => (
            <div key={i} className="bg-slate-50 border border-slate-100 rounded-xl p-4 flex flex-col gap-3">
              <div className="h-4 bg-slate-200 rounded w-20 animate-pulse"></div>
              <div className="h-4 bg-slate-200 rounded w-32 animate-pulse"></div>
            </div>
          ))
        ) : preAprobadas.length === 0 ? (
          <div className="py-8 text-center bg-slate-50 rounded-xl border border-dashed border-slate-200">
            <p className="text-slate-400 font-medium text-sm">No hay solicitudes recientes.</p>
          </div>
        ) : (
          paginatedRequests.map((req, idx) => (
            <div 
              key={idx}
              onClick={() => {
                const tipo = req.type?.toLowerCase();
                const basePath = tipo === 'combustible' ? '/combustible/aprobaciones' 
                               : tipo === 'mantenimiento' ? '/mantenimiento/aprobaciones' 
                               : '/aprobaciones';
                navigate(`${basePath}/${req.code}`);
              }}
              className="bg-white border border-slate-100 shadow-sm rounded-xl p-4 flex flex-col gap-3 cursor-pointer hover:border-indigo-200 transition-colors"
            >
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 bg-[#4F46E5] rounded-full"></span>
                  <span className="font-bold text-[#182645] text-sm">{req.code}</span>
                </div>
                {getStatusBadge(req.status)}
              </div>
              <div className="flex justify-between items-center text-xs text-slate-500">
                <span>{req.date}</span>
                <span className="font-medium bg-slate-100 px-2 py-1 rounded-md">{req.type || 'Transporte'}</span>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Desktop View (Table) */}
      <div className="hidden md:block overflow-x-auto p-2">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="border-b border-slate-100/80">
              <th className="py-4 px-6 text-[10px] font-bold text-slate-400 uppercase tracking-widest">C├ôDIGO</th>
              <th className="py-4 px-6 text-[10px] font-bold text-slate-400 uppercase tracking-widest">FECHA</th>
              <th className="py-4 px-6 text-[10px] font-bold text-slate-400 uppercase tracking-widest">TIPO</th>
              <th className="py-4 px-6 text-[10px] font-bold text-slate-400 uppercase tracking-widest text-right">ESTADO</th>
