import { useState, useEffect } from 'react';
import { ComparativaResponse, DecisionType } from '../types';
import { solicitudApi } from '../api/solicitudApi';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';

export function useAprobacion(id: string | undefined) {
  const [data, setData] = useState<ComparativaResponse | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [decision, setDecision] = useState<DecisionType>('ninguna');
  const [comentario, setComentario] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const navigate = useNavigate();

  useEffect(() => {
    if (!id) return;

    const fetchComparativa = async () => {
      try {
        setIsLoading(true);
        const result = await solicitudApi.getComparativa(id);
        setData(result);

        if (result.solicitud?.decision_final) {
          setDecision(result.solicitud.decision_final);
        }
        if (result.solicitud?.comentario_jefe) {
          setComentario(result.solicitud.comentario_jefe);
        }
      } catch (err: any) {
        const msg = err.response?.data?.message || 'Error al cargar la solicitud';
        setError(msg);
        toast.error(msg);
      } finally {
        setIsLoading(false);
      }
    };

    fetchComparativa();
  }, [id]);

  const confirmarAprobacion = async () => {
    if (!id || decision === 'ninguna') return;

    try {
      setIsSubmitting(true);
      await solicitudApi.aprobarConDecision(id, decision, comentario);
      toast.success('Solicitud procesada exitosamente');
      navigate('/');
    } catch (err: any) {
      const responseData = err.response?.data;
      let msg = responseData?.message || 'Error al aprobar la solicitud';
      if (err.response?.status === 422 && responseData?.errors) {
        const firstError = Object.values(responseData.errors)[0] as string[];
        msg = firstError[0] || 'Datos inv├ílidos (422)';
      }
      setError(msg);
      toast.error(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDesbloquear = async () => {
     if(!id) return;
     try {
       setIsSubmitting(true);
       await solicitudApi.desbloquear(id);
       toast.success('Solicitud desbloqueada correctamente');
       navigate('/');
     } catch(err:any) {
       const msg = err.response?.data?.message || 'Error al desbloquear';
       setError(msg);
       toast.error(msg);
     } finally {
       setIsSubmitting(false);
     }
  };

  const handleProgramar = async () => {
    if (!id) return;
    try {
      setIsSubmitting(true);
      await solicitudApi.programar(id);
      toast.success('Solicitud programada exitosamente');
      navigate('/');
    } catch (err: any) {
      const msg = err.response?.data?.message || 'Error al programar';
      setError(msg);
      toast.error(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRechazar = async () => {
    if (!id) return;
    // Si queremos validar que haya comentario localmente antes de enviar:
    // if (!comentario.trim()) { setError('Debe ingresar un comentario para rechazar'); return; }
    try {
      setIsSubmitting(true);
      await solicitudApi.rechazar(id, comentario);
      toast.success('Solicitud rechazada');
      navigate('/');
    } catch (err: any) {
      const msg = err.response?.data?.message || 'Error al rechazar la solicitud';
      setError(msg);
      toast.error(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  return {
    data,
    isLoading,
    error,
    decision,
    setDecision,
    comentario,
    setComentario,
    confirmarAprobacion,
    handleDesbloquear,
    handleProgramar,
    handleRechazar,
    isSubmitting
  };
}

import { useState, useEffect } from 'react';
import { ComparativaCombustibleResponse } from '../types';
import { solicitudCombustibleApi } from '../api/solicitudCombustibleApi';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';

export function useAprobacionCombustible(id: string | undefined) {
  const [data, setData] = useState<ComparativaCombustibleResponse | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [comentario, setComentario] = useState('');
  const [tipoDecision, setTipoDecision] = useState<'operativo' | 'jefe'>('operativo');
  const [montoManual, setMontoManual] = useState<number | ''>('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const navigate = useNavigate();

  useEffect(() => {
    if (!id) return;

    const fetchComparativa = async () => {
      try {
        setIsLoading(true);
        const result = await solicitudCombustibleApi.getComparativa(id);
        setData(result);

        if (result.solicitud?.comentario_jefe) {
          setComentario(result.solicitud.comentario_jefe);
        }
      } catch (err: any) {
        const msg = err.response?.data?.message || 'Error al cargar la solicitud';
        setError(msg);
        toast.error(msg);
      } finally {
        setIsLoading(false);
      }
    };

    fetchComparativa();
  }, [id]);

  const confirmarAprobacion = async () => {
    if (!id) return;

    if (tipoDecision === 'jefe' && (!montoManual || Number(montoManual) <= 0)) {
      const msg = 'Debe ingresar una cantidad v├ílida de cargas para aprobar manualmente';
      setError(msg); 
      toast.error(msg); 
      return;
    }

    try {
      setIsSubmitting(true);
      setError(null);
      await solicitudCombustibleApi.aprobarConDecision(
        id, 
        tipoDecision, 
        comentario || 'Aprobado por jefatura', 
        tipoDecision === 'jefe' ? Number(montoManual) : undefined
      );
      toast.success('Solicitud procesada exitosamente');
      navigate('/');
    } catch (err: any) {
      const msg = err.response?.data?.message || 'Error al aprobar la solicitud';
      setError(msg);
      toast.error(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleObservacion = async () => {
    if (!id) return;
    if (!comentario.trim()) { 
      const msg = 'Debe ingresar un comentario para enviar una observaci├│n';
      setError(msg); toast.error(msg); return; 
    }
    try {
      setIsSubmitting(true); setError(null);
      await solicitudCombustibleApi.observacion(id, comentario);
      toast.success('Observaci├│n registrada');
      navigate('/');
    } catch (err: any) {
      const msg = err.response?.data?.message || 'Error al registrar la observaci├│n';
      setError(msg); toast.error(msg);
    } finally { setIsSubmitting(false); }
  };

  const handlePreAprobar = async () => {
    if (!id) return;
    try {
      setIsSubmitting(true); setError(null);
      await solicitudCombustibleApi.preAprobar(id, comentario || 'Pre-aprobado por jefatura');
      toast.success('Solicitud pre-aprobada');
      navigate('/');
    } catch (err: any) {
      const msg = err.response?.data?.message || 'Error al pre-aprobar la solicitud';
      setError(msg); toast.error(msg);
    } finally { setIsSubmitting(false); }
  };

  const handleRechazar = async () => {
    if (!id) return;
    if (!comentario.trim()) { 
      const msg = 'Debe ingresar un comentario para rechazar';
      setError(msg); 
      toast.error(msg);
      return; 
    }
    try {
      setIsSubmitting(true);
      setError(null);
      await solicitudCombustibleApi.rechazar(id, comentario);
      toast.success('Solicitud rechazada');
      navigate('/');
    } catch (err: any) {
      const msg = err.response?.data?.message || 'Error al rechazar la solicitud';
      setError(msg);
      toast.error(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  return {
    data,
    isLoading,
    error,
    comentario,
    setComentario,
    tipoDecision,
    setTipoDecision,
    montoManual,
    setMontoManual,
    confirmarAprobacion,
    handleObservacion,
    handlePreAprobar,
    handleRechazar,
    isSubmitting
  };
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import { solicitudMantenimientoApi } from '../api/solicitudMantenimientoApi';
import { SolicitudMantenimientoDetalle } from '../types';

export function useAprobacionMantenimiento(id: string | undefined) {
  const navigate = useNavigate();
  const [data, setData] = useState<SolicitudMantenimientoDetalle | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [comentario, setComentario] = useState('');

  useEffect(() => {
    if (!id) return;

    const fetchData = async () => {
      try {
        setIsLoading(true);
        const result = await solicitudMantenimientoApi.getById(id);
        setData(result);
        setError(null);
      } catch (err: any) {
        console.error('Error cargando la solicitud de mantenimiento:', err);
        setError(err.response?.data?.message || 'Error al cargar la solicitud');
        toast.error('No se pudo cargar la solicitud');
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [id]);

  const handleAprobar = async () => {
    if (!id) return;

    // Para mantenimiento, no exigimos comentario en la aprobaci├│n obligatoriamente,
    // pero si lo escribieron lo mandamos. (Podemos poner un default si el backend lo exige).
    const obs = comentario.trim() || 'Aprobado por jefatura.';

    try {
      setIsSubmitting(true);
      await solicitudMantenimientoApi.aprobar(id, obs);
      toast.success('Mantenimiento aprobado oficialmente');
      navigate('/');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Error al aprobar la solicitud');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRechazar = async () => {
    if (!id) return;
    if (!comentario.trim()) {
      toast.error('Debe ingresar un comentario para rechazar');
      return;
    }

    try {
      setIsSubmitting(true);
      await solicitudMantenimientoApi.rechazar(id, comentario.trim());
      toast.success('Solicitud rechazada');
      navigate('/');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Error al rechazar la solicitud');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleObservacion = async () => {
    if (!id) return;
    if (!comentario.trim()) {
      toast.error('Debe ingresar un comentario');
      return;
    }

    try {
      setIsSubmitting(true);
      await solicitudMantenimientoApi.observacion(id, comentario.trim());
      toast.success('Observaci├│n guardada. Regresando al panel...');
      navigate('/');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Error al guardar observaci├│n');
    } finally {
      setIsSubmitting(false);
    }
  };

  return {
    data,
    isLoading,
    error,
    comentario,
    setComentario,
    handleAprobar,
    handleRechazar,
    handleObservacion,
    isSubmitting
  };
}

import { useState } from 'react';
import { toast } from 'sonner';
import { axiosClient } from '../../../shared/api/axiosClient';
import { solicitudApi, RecursoDisponible } from '../api/solicitudApi';

export function useReasignacion(id: string | undefined, onSuccess: () => void) {
  const [showReasignarModal, setShowReasignarModal] = useState(false);
  const [recursos, setRecursos] = useState<RecursoDisponible | null>(null);
  const [loadingRecursos, setLoadingRecursos] = useState(false);
  const [selectedVehiculo, setSelectedVehiculo] = useState<number | ''>('');
  const [selectedMotorista, setSelectedMotorista] = useState<number | ''>('');
  const [motivoReasignacion, setMotivoReasignacion] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const openReasignarModal = async (fechaS: any, fechaR: any) => {
    setShowReasignarModal(true);
    setLoadingRecursos(true);
    try {
      // @ts-ignore
      const result = await solicitudApi.getRecursosDisponibles(fechaS, fechaR);
      setRecursos(result);
    } catch (_err) {
      try {
        const [vRes, mRes] = await Promise.all([
          axiosClient.get('/catalogos/vehiculos/disponibles'),
          axiosClient.get('/catalogos/motoristas/disponibles')
        ]);
        setRecursos({
          vehiculos: Array.isArray(vRes.data) ? vRes.data : [],
          motoristas: Array.isArray(mRes.data) ? mRes.data : []
        });
      } catch (_err2) {
        setRecursos({ vehiculos: [], motoristas: [] });
      }
    } finally {
      setLoadingRecursos(false);
    }
  };

  const handleReasignar = async () => {
    if (!id || !selectedVehiculo || !selectedMotorista || !motivoReasignacion.trim()) return;
    try {
      setIsSubmitting(true);
      // @ts-ignore
      await solicitudApi.reasignar(id, Number(selectedVehiculo), Number(selectedMotorista), motivoReasignacion);
      toast.success('┬íReasignaci├│n exitosa! El motorista y veh├¡culo han sido actualizados.');
      setShowReasignarModal(false);
      onSuccess();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Error al reasignar recursos.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return {
    showReasignarModal,
    setShowReasignarModal,
    recursos,
    loadingRecursos,
    selectedVehiculo,
    setSelectedVehiculo,
    selectedMotorista,
    setSelectedMotorista,
    motivoReasignacion,
    setMotivoReasignacion,
    isSubmitting,
    openReasignarModal,
    handleReasignar
  };
}

import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowLeft, MapPin, Calendar, Clock, FileText, User, Car, RefreshCw, CheckCircle, XCircle } from 'lucide-react';
import { axiosClient } from '../../../shared/api/axiosClient';
import { ModalDestinoAdicional } from '../components/ModalDestinoAdicional';
import { useReasignacion } from '../hooks/useReasignacion';
import { ModalReasignarViaje } from '../components/ModalReasignarViaje';

export interface HistorialDataDetalle {
  raw?: any;
  comparativa?: any;
}

export default function HistorialDetallePage() {
  const { id } = useParams();
  const [data, setData] = useState<HistorialDataDetalle | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Reasignaci├│n
  const {
    showReasignarModal, setShowReasignarModal, recursos, loadingRecursos,
    selectedVehiculo, setSelectedVehiculo, selectedMotorista, setSelectedMotorista,
    motivoReasignacion, setMotivoReasignacion, isSubmitting, openReasignarModal, handleReasignar
  } = useReasignacion(id, () => {
    Promise.all([
      axiosClient.get(`/solicitudes-transporte/${id}`),
      axiosClient.get(`/solicitudes-transporte/${id}/comparativa`)
    ]).then(([showRes, compRes]) => {
      setData({ raw: showRes.data.data || showRes.data, comparativa: compRes.data });
    });
  });

  // Destino Adicional
  const [showDestinoModal, setShowDestinoModal] = useState(false);

  useEffect(() => {
    if (!id) return;
    const fetchData = async () => {
      try {
        setIsLoading(true);
        let showData = null;
        let compData = null;

        const isCombustible = id?.startsWith('CB-');
        const endpoint = isCombustible ? `/solicitudes-combustible/${id}` : `/solicitudes-transporte/${id}`;

        // 1. Obtener los datos reales finales (estado, asignaci├│n real)
        try {
          const showRes = await axiosClient.get(endpoint);
          showData = showRes.data.data || showRes.data;
        } catch (e) {
          console.error('Error fetching show data', e);
        }

        // 2. Obtener la comparativa (para datos de sugerencias si aplica)
        try {
          const compRes = await axiosClient.get(`${endpoint}/comparativa`);
          compData = compRes.data;
        } catch (e) {
          console.error('Error fetching comparativa data', e);
        }

        if (!showData && !compData) {
          setError('No se pudo cargar el detalle de la solicitud.');
          return;
        }

        setData({ raw: showData, comparativa: compData });
      } catch (err: any) {
        setError(err.response?.data?.message || 'Error inesperado al cargar.');
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, [id]);



  if (isLoading) {
    return (
      <div className="flex-1 p-8 flex items-center justify-center min-h-[50vh]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#859BFF]"></div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="flex-1 p-4 md:p-8 flex flex-col items-center justify-center min-h-[50vh]">
        <p className="text-red-500 mb-4 font-medium">{error || 'Solicitud no encontrada'}</p>
        <Link to="/historial" className="text-[#859BFF] hover:underline flex items-center gap-2">
          <ArrowLeft size={16} /> Volver al Historial
        </Link>
      </div>
    );
  }

  const raw = data.raw || {};
  const comp = data.comparativa?.solicitud || {};

  // Preferimos raw porque es la fuente de la verdad para solicitudes ya aprobadas
  const statusRaw = raw.estado || raw.status || comp.status || comp.estado || '';
  const status = typeof statusRaw === 'string' ? statusRaw.toLowerCase() : (statusRaw.value || '').toLowerCase();

  const isAprobada = status.includes('aprobada') || status.includes('programada');
  const isRechazada = status.includes('rechazada');
  const isEnEjecucion = status.includes('ejecucion');

  const getStatusColor = () => {
    if (isAprobada) return { bg: 'bg-emerald-50', border: 'border-emerald-200', text: 'text-emerald-700', dot: 'bg-emerald-500', label: 'Aprobada' };
    if (isRechazada) return { bg: 'bg-red-50', border: 'border-red-200', text: 'text-red-700', dot: 'bg-red-500', label: 'Rechazada' };
    if (status.includes('ejecucion')) return { bg: 'bg-indigo-50', border: 'border-indigo-200', text: 'text-indigo-700', dot: 'bg-indigo-500', label: 'En Ejecuci├│n' };
    return { bg: 'bg-slate-50', border: 'border-slate-200', text: 'text-slate-700', dot: 'bg-slate-500', label: status || 'Desconocido' };
  };

  const statusInfo = getStatusColor();
  const fechaSalidaVal = raw.fecha_salida || comp.fechas?.salida;
  const fechaRetornoVal = raw.fecha_retorno || comp.fechas?.retorno;

  const isCombustibleView = (raw.codigo || comp.codigo || id)?.toString().startsWith('CB-');

  // Reasignar solo permitido antes de la ejecuci├│n y SOLO para Transporte (nunca para Combustible)
  const canReasignar = !isCombustibleView && (status === 'pre_aprobada' || status === 'aprobada' || status === 'programada');

  // A├▒adir destino adicional solo en ejecuci├│n
  const canAddDestino = !isCombustibleView && status === 'en_ejecucion';

  // Valores a mostrar
  const solicitanteName = raw.solicitante?.name || raw.solicitante?.nombre || (typeof raw.solicitante === 'string' ? raw.solicitante : '') || comp.solicitante || 'N/A';
  const destino = raw.destino || comp.destino || raw.destino_actividad || 'N/A';
  const horasEstimadas = Math.abs(raw.horas_estimadas || comp.horas_estimadas || 0);
  const motivo = raw.motivo || comp.motivo || raw.observaciones || 'Sin motivo';
  const decisionFinal = raw.decision_final || comp.decision_final || status;

  // Asignaciones finales
  const motoristaFinal = raw.motorista?.nombre || comp.motorista_nombre || data.comparativa?.operativo?.motorista?.nombre || data.comparativa?.operativo?.autor || 'Sin asignar';
  const vehiculoFinal = raw.vehiculo?.placa || comp.vehiculo_placa || data.comparativa?.operativo?.vehiculo?.placa || 'Sin asignar';
  const vehiculoMarca = raw.vehiculo?.marca || comp.vehiculo_marca || data.comparativa?.operativo?.vehiculo?.marca || '';

  // El jefe guarda su decisi├│n manual en cantidad_combustible (en show API) o cantidad_estimada (en comparativa API)
  const montoFinal = raw.cantidad_combustible || comp.cantidad_estimada || raw.monto_aprobado || comp.monto_aprobado || data.comparativa?.operativo?.monto_aprobado || null;
  const comentarioJefe = raw.comentario_jefe || comp.comentario_jefe || raw.comentario || 'Sin comentario';

  // Prioridad
  const prioridadRaw = raw.prioridad_grupo?.value || raw.prioridad_grupo || comp.prioridad_grupo || raw.prioridad?.value || raw.prioridad || comp.prioridad || 'N/A';
  const prioridad = typeof prioridadRaw === 'string' ? prioridadRaw.toLowerCase() : prioridadRaw;
  const getPrioridadColor = (p: string) => {
    if (p.includes('alta') || p.includes('urgente')) return 'bg-red-50 text-red-700 border-red-200';
    if (p.includes('media')) return 'bg-amber-50 text-amber-700 border-amber-200';
    if (p === 'n/a') return 'bg-slate-50 text-slate-700 border-slate-200';
    return 'bg-blue-50 text-blue-700 border-blue-200';
  };

  return (
    <div className="p-4 md:p-8 pb-20 md:pb-12 max-w-5xl mx-auto">
      {/* Header */}
      <div className="mb-6 border-b border-slate-200 pb-4 mt-2">
        <Link to="/historial" className="inline-flex items-center gap-2 text-sm text-slate-500 hover:text-slate-800 transition-colors mb-3">
          <ArrowLeft size={16} /> Volver al Historial
        </Link>
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-3">
          <div>
            <h1 className="text-xl md:text-2xl font-bold text-slate-800 tracking-tight">
              Detalle de Solicitud <span className="text-slate-500 font-medium">#{raw.codigo || comp.codigo || id}</span>
            </h1>
            <p className="text-slate-500 mt-1 text-sm">Informaci├│n completa del proceso.</p>
          </div>
          <span className={`px-4 py-1.5 ${statusInfo.bg} ${statusInfo.border} border rounded-full text-sm font-semibold ${statusInfo.text} flex items-center gap-2 shadow-sm`}>
            <span className={`w-2 h-2 rounded-full ${statusInfo.dot}`}></span>
            {statusInfo.label}
          </span>
        </div>
      </div>

      {/* Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
        {/* Card: Datos del Viaje / Combustible */}
        <div className="bg-white rounded-xl p-6 shadow-sm border border-slate-200">
          <div className="flex items-center gap-2 mb-5 pb-4 border-b border-slate-200">
            <FileText className="text-slate-400" size={18} />
            <h3 className="font-bold text-slate-800 text-lg tracking-tight">{isCombustibleView ? 'Datos de Combustible' : 'Datos del Viaje'}</h3>
          </div>
          <div className="space-y-4">
            <div className="flex justify-between items-start gap-4">
              <div>
                <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1">Solicitante</p>
                <p className="text-sm text-slate-800 font-medium">{solicitanteName}</p>
              </div>
              <div className="text-right">
                <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1">Prioridad</p>
                <span className={`inline-block px-2.5 py-0.5 rounded text-xs font-bold capitalize border ${getPrioridadColor(prioridad)}`}>
                  {prioridadRaw}
                </span>
              </div>
            </div>

            {!isCombustibleView && (
              <>
                <div>
                  <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                    <MapPin size={12} /> Destino
                  </p>
                  <p className="text-sm text-slate-800 font-medium">{destino}</p>
                </div>
                <div className="grid grid-cols-2 gap-px bg-slate-200 border border-slate-200 overflow-hidden rounded-lg">
                  <div className="bg-slate-50 p-3">
                    <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                      <Calendar size={12} /> Salida
                    </p>
                    <p className="text-xs text-slate-800 font-medium">
                      {fechaSalidaVal ? new Date(fechaSalidaVal).toLocaleString() : 'N/A'}
                    </p>
                  </div>
                  <div className="bg-slate-50 p-3">
                    <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                      <Calendar size={12} /> Retorno
                    </p>
                    <p className="text-xs text-slate-800 font-medium">
                      {fechaRetornoVal ? new Date(fechaRetornoVal).toLocaleString() : 'N/A'}
                    </p>
                  </div>
                </div>
                <div>
                  <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                    <Clock size={12} /> Horas Estimadas
                  </p>
                  <p className="text-sm text-slate-800 font-medium">{horasEstimadas} hrs</p>
                </div>
              </>
            )}

            {isCombustibleView && (
              <div>
                <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                  <Calendar size={12} /> Fecha de Solicitud
                </p>
                <p className="text-sm text-slate-800 font-medium">
                  {raw.created_at ? new Date(raw.created_at).toLocaleString() : (comp.fecha_solicitud ? new Date(comp.fecha_solicitud).toLocaleString() : 'N/A')}
                </p>
              </div>
            )}

            <div>
              <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1">Motivo / Observaci├│n</p>
              <p className="text-sm text-slate-600 bg-slate-50 p-3 rounded-lg border border-slate-200 italic">
                "{motivo}"
              </p>
            </div>
          </div>
        </div>

        {/* Card: Asignaci├│n Actual */}
        <div className="bg-white rounded-xl p-6 shadow-sm border border-slate-200">
          <div className="flex items-center gap-2 mb-5 pb-4 border-b border-slate-200">
            {isEnEjecucion ? <MapPin className="text-indigo-500" size={18} /> : (isAprobada ? <CheckCircle className="text-emerald-500" size={18} /> : <XCircle className="text-red-500" size={18} />)}
            <h3 className="font-bold text-slate-800 text-lg tracking-tight">
              {isEnEjecucion ? 'Viaje en Curso' : (isAprobada ? 'Asignaci├│n Aprobada' : 'Decisi├│n Final')}
            </h3>
          </div>
          <div className="space-y-4">
            <div>
              <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1">Estado Actual</p>
              <span className={`inline-block px-3 py-1 rounded-full text-xs font-bold capitalize border ${statusInfo.bg} ${statusInfo.text} ${statusInfo.border}`}>
                {decisionFinal}
              </span>
            </div>

            {isCombustibleView ? (
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                    <FileText size={12} /> Cargas Aprobadas
                  </p>
                  <p className="text-xl font-black text-emerald-600">
                    {montoFinal !== null && montoFinal !== undefined ? `$${Number(montoFinal).toFixed(2)}` : 'Sin asignar'}
                  </p>
                </div>
                <div>
                  <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                    <Car size={12} /> Veh├¡culo (Placa)
                  </p>
                  <p className="text-sm font-bold text-slate-800">
                    {vehiculoFinal}
                  </p>
                  {vehiculoMarca && (
                    <p className="text-xs text-slate-500">
                      {vehiculoMarca}
                    </p>
                  )}
                </div>
              </div>
            ) : (
              <>
                <div>
                  <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                    <User size={12} /> Motorista Asignado
                  </p>
                  <p className="text-sm text-slate-800 font-medium">
                    {motoristaFinal}
                  </p>
                </div>

                <div>
                  <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                    <Car size={12} /> Veh├¡culo Asignado
                  </p>
                  <p className="text-sm text-slate-800 font-medium">
                    {vehiculoFinal}
                  </p>
                  {vehiculoMarca && (
                    <p className="text-xs text-slate-500">
                      {vehiculoMarca}
                    </p>
                  )}
                </div>
              </>
            )}

            <div>
              <p className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1">Comentario del Jefe</p>
              <p className="text-sm text-slate-600 bg-slate-50 p-3 rounded-lg border border-slate-200 italic">
                "{comentarioJefe}"
              </p>
            </div>
          </div>

          {/* Bot├│n de Reasignar */}
          {canReasignar && (
            <div className="mt-6 pt-4 border-t border-slate-200">
              <button
                onClick={() => openReasignarModal(fechaSalidaVal, fechaRetornoVal)}
